groups:
- name: system_alerts
  rules:
  - alert: HighCPU
    expr: cpu_usage_percent > {cpu_threshold}
    for: 5m
    labels: {severity: warning}
    annotations: {summary: "CPU使用率超过阈值"}
  - alert: HighMemory
    expr: mem_usage_percent > {mem_threshold}
    for: 5m
  - alert: DiskFull
    expr: disk_usage_percent > {disk_threshold}
    for: 1m

server {
    listen 443 ssl http2;
    server_name {domain};
    ssl_certificate /etc/ssl/{domain}.pem;
    ssl_certificate_key /etc/ssl/{domain}.key;
    location / {
        proxy_pass http://{backend};
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
    location /static/ {
        root /var/www;
        expires 30d;
    }
}

apiVersion: apps/v1
kind: Deployment
metadata: {name: {service-name}}
spec:
  replicas: {count}
  selector: {matchLabels: {app: {service-name}}}
  template:
    metadata: {labels: {app: {service-name}}}
    spec:
      containers:
      - name: {service-name}
        image: {image}:{tag}
        ports: [{containerPort: {port}}]
        resources:
          requests: {cpu: 100m, memory: 128Mi}
          limits: {cpu: 500m, memory: 512Mi}
---
apiVersion: v1
kind: Service
metadata: {name: {service-name}}
spec:
  type: ClusterIP
  ports: [{port: 80, targetPort: {port}}]
  selector: {app: {service-name}}

Host {alias}-dev
    HostName {dev_ip}
    User {username}
    IdentityFile ~/.ssh/id_ed25519

Host {alias}-staging
    HostName {staging_ip}
    User {username}
    ProxyJump {bastion_host}

Host {alias}-prod
    HostName {prod_ip}
    User {username}
    ProxyJump {bastion_host}
    StrictHostKeyChecking yes
